version: 1
base_currency: PLN
buckets:
  - id: equity.eu
    match: {asset_class: equity}
  - id: cash
    match: {asset_class: cash}
allocation:
  targets: {equity.eu: 0.8, cash: 0.2}
rules:
  - id: synthetic_loss
    kind: loss_from_cost
    params: {threshold: 0.1, instrument_ids: ['1']}
review: {every: 2weeks, day: thursday, cards: [world, positions, events, calendar, decide]}

