CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
INSERT INTO "alembic_version" VALUES('0030_sync_outbox_post');
CREATE TABLE alerts (
	id INTEGER NOT NULL, 
	profile_id INTEGER NOT NULL, 
	instrument_id INTEGER, 
	scope VARCHAR NOT NULL, 
	kind VARCHAR NOT NULL, 
	params JSON NOT NULL, 
	polarity VARCHAR NOT NULL, 
	severity VARCHAR NOT NULL, 
	title VARCHAR NOT NULL, 
	note VARCHAR, 
	source VARCHAR NOT NULL, 
	created_by VARCHAR NOT NULL, 
	status VARCHAR NOT NULL, 
	cooldown_days INTEGER, 
	expires_at DATETIME, 
	snoozed_until DATETIME, 
	last_triggered_at DATETIME, 
	last_checked_at DATETIME, 
	last_value VARCHAR, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, deleted_at DATETIME, tag VARCHAR, 
	PRIMARY KEY (id), 
	CONSTRAINT fk_alerts_profile_id FOREIGN KEY(profile_id) REFERENCES profiles (id), 
	FOREIGN KEY(instrument_id) REFERENCES inv_instruments (id)
);
INSERT INTO "alerts" VALUES(1,1,1,'instrument','price_above','{"level": 11}','positive','action','Synthetic alert',NULL,'user','user','triggered',NULL,'2026-09-29 00:00:00.000000',NULL,'2026-09-30 10:00:00.000000',NULL,NULL,'2026-09-01 08:00:00.000000','2026-09-30 10:00:00.000000',NULL,NULL);
CREATE TABLE asset_details (
	id INTEGER NOT NULL, 
	account_id INTEGER NOT NULL, 
	note VARCHAR, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(account_id) REFERENCES accounts (id)
);
CREATE TABLE balances (
	id INTEGER NOT NULL, 
	account_id INTEGER NOT NULL, 
	date DATE NOT NULL, 
	amount VARCHAR NOT NULL, 
	currency VARCHAR NOT NULL, 
	source VARCHAR(12) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_balance_day UNIQUE (account_id, date, source), 
	FOREIGN KEY(account_id) REFERENCES accounts (id)
);
CREATE TABLE "category_rules" (
	id INTEGER NOT NULL, 
	merchant_key VARCHAR NOT NULL, 
	category VARCHAR NOT NULL, 
	source VARCHAR NOT NULL, 
	locked BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	profile_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_rule_profile_merchant UNIQUE (profile_id, merchant_key), 
	CONSTRAINT fk_category_rules_profile_id FOREIGN KEY(profile_id) REFERENCES profiles (id)
);
CREATE TABLE change_events (
	id INTEGER NOT NULL, 
	ts DATETIME NOT NULL, 
	profile_id INTEGER, 
	entity VARCHAR NOT NULL, 
	op VARCHAR NOT NULL, 
	ref VARCHAR, 
	payload JSON, 
	PRIMARY KEY (id)
);
